39		initLocalCluster.Do(func() {
40			info, err := db.kubeclientset.Discovery().ServerVersion()
41			if err == nil {
42				ver, verErr := version.ParseGeneric(info.GitVersion)
43				if verErr == nil {
44					localCluster.Info.ServerVersion = ver.String()
45				} else {
46					log.Warnf("Failed to parse Kubernetes server version: %v", verErr)
47				}
48				localCluster.Info.ConnectionState = appv1.ConnectionState{Status: appv1.ConnectionStatusSuccessful}
49			} else {
50				localCluster.Info.ConnectionState = appv1.ConnectionState{
51					Status:  appv1.ConnectionStatusFailed,
52					Message: err.Error(),
53				}
54			}
55		})
56		cluster := localCluster.DeepCopy()
57		now := metav1.Now()
58		cluster.Info.ConnectionState.ModifiedAt = &now
