	if time.Since(c.lastUpdated) < clusterInfoTimeout {
		return
	}

	ctx, cancel := context.WithTimeout(context.Background(), clusterInfoTimeout)
	defer func() {
		cancel()
		c.lastUpdated = time.Now()
	}()

